contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log) public {
        bool beforeInitialized;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { beforeInitialized = false; } else { beforeInitialized = true; }

        // Read pre-call state through public surface.
        uint preBalance = address(c).balance;

        // The deciding call: must be its own top-level statement.
        bool reverted;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: SetLogFile reverts iff already initialized; on success
        // ether balance is unchanged.
        uint postBalance = address(c).balance;
        assert(reverted == beforeInitialized);
    }

    receive() external payable {}
}

